import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"项目概览","description":"","frontmatter":{},"headers":[],"relativePath":"guide/overview.md","filePath":"guide/overview.md","lastUpdated":1790405974000}'),o={name:"guide/overview.md"};function i(l,t,n,s,h,c){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="项目概览" tabindex="-1">项目概览 <a class="header-anchor" href="#项目概览" aria-label="Permalink to &quot;项目概览&quot;">​</a></h1><p>ChatCMS 是面向 <strong>新媒体种草</strong> 的开源桌面 Agent：基于 <strong>Tauri v2 + React</strong>，把智能会话、多角色代理、内容笔记、图片/视频工厂、媒体采集与发布放在同一套本地工作台里。</p><h2 id="种草场景你能做什么" tabindex="-1">种草场景你能做什么 <a class="header-anchor" href="#种草场景你能做什么" aria-label="Permalink to &quot;种草场景你能做什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>能力</th></tr></thead><tbody><tr><td>洞察</td><td>媒体采集、知识库沉淀爆款与话术</td></tr><tr><td>创作</td><td>智能会话 + 多 Agent、内容笔记、图片/视频工厂</td></tr><tr><td>发布</td><td>插件脚本、发布桥接、账号保险柜</td></tr><tr><td>运营</td><td>调度中心、意图规则、权限与会话观测</td></tr></tbody></table><h2 id="工作台地图" tabindex="-1">工作台地图 <a class="header-anchor" href="#工作台地图" aria-label="Permalink to &quot;工作台地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>区域</th><th>能力</th></tr></thead><tbody><tr><td>工作台</td><td>智能会话、业务地图、内容管理、图片/视频工厂、调度中心</td></tr><tr><td>媒体管理</td><td>采集任务、插件脚本、账号保险柜</td></tr><tr><td>智能配置</td><td>代理档案、技能、MCP、模型、意图规则、知识库</td></tr><tr><td>系统设置</td><td>权限、渠道、运行观测</td></tr></tbody></table><h2 id="三种会话模式" tabindex="-1">三种会话模式 <a class="header-anchor" href="#三种会话模式" aria-label="Permalink to &quot;三种会话模式&quot;">​</a></h2><ul><li><strong>Ask</strong>：纯问答，不调用工具</li><li><strong>Agent</strong>：带内置工具与 MCP，可注入技能与知识（种草执行主模式）</li><li><strong>Search</strong>：侧重知识库检索增强回答</li></ul><p>模式在输入区切换；<strong>主 Agent</strong> 在顶栏选择（可自动选角或固定某一角色，例如「种草文案」「短视频策划」）。</p><h2 id="技术栈" tabindex="-1">技术栈 <a class="header-anchor" href="#技术栈" aria-label="Permalink to &quot;技术栈&quot;">​</a></h2><ul><li>前端：React 19 · Vite · Zustand · CabinX</li><li>后端：Rust · Tauri v2 · SQLite</li><li>运行分层：<code>session → intent → decision → plan ⇄ execute → response</code></li></ul><p>更细的循环说明见 <a href="/concepts/agent-loop">Agent Loop</a>。</p><h2 id="相关仓库" tabindex="-1">相关仓库 <a class="header-anchor" href="#相关仓库" aria-label="Permalink to &quot;相关仓库&quot;">​</a></h2><ul><li>本仓库：桌面端与文档站</li><li>采集 Worker：可选连接 <code>chatcms-collect</code>（默认 <code>http://127.0.0.1:8080</code>）</li></ul>',14)])])}const b=e(o,[["render",i]]);export{p as __pageData,b as default};
